// File: the launch file: every setting of one start of the game. Takes about, bundle, board, widescreen,
// trueWidescreen, windowName, showFrameRate, rumble, present, refreshRate, verticalSync, fullScreen, controllerSetup;
// by hand: windowNamePicture, taskbar, lanes, match, replay, debug.
template <typename P, typename T>
void ReadFile([[maybe_unused]] P& p, [[maybe_unused]] T* t)
{
  p.Words("about", &t->about);
  if (!p.Has("about"))
    p.Refuse("about", "is missing: a line that says what this start is for");
  p.Words("bundle", &t->bundle_dir);
  p.Words("board", &t->board);
  p.Flag("widescreen", &t->widescreen);
  p.Flag("trueWidescreen", &t->true_widescreen);
  p.Words("windowName", &t->window_name);
  p.Flag("showFrameRate", &t->show_frame_rate);
  p.Flag("rumble", &t->rumble);
  p.OneOf("present", &t->present, {"field", "console", "copy"});
  p.OneOf("refreshRate", &t->refresh_rate, {"60", "120", "240", "display"});
  p.Flag("verticalSync", &t->vertical_sync);
  p.OneOf("fullScreen", &t->full_screen, {"borderless", "exclusive"});
  p.Flag("controllerSetup", &t->controller_setup);
}

// Match ("match"): a race: the match file the launcher wrote, with where the race is recorded. Takes relayHost, delay,
// overclock, otherSounds, record, rejoin, spectate, practice, camera; by hand: match.
template <typename P, typename T>
void ReadMatch([[maybe_unused]] P& p, [[maybe_unused]] T* t)
{
  if (!p.Has("match"))
    p.Refuse("match", "is missing: the coordinator's match start");
  p.Words("relayHost", &t->relay_host, true);
  p.Whole("delay", &t->delay, 0u, 2u);
  p.Number("overclock", &t->cpu_clock, 1.0, 16.0);
  p.OneOf("otherSounds", &t->other_sounds, {"full", "quieter", "off"});
  p.Words("record", &t->replay_file);
  p.Flag("rejoin", &t->rejoin);
  p.Flag("spectate", &t->spectate);
  p.Flag("practice", &t->practice);
  p.Whole("camera", &t->camera, 1u, 4u);
}

// Replay ("replay"): a replay's playback, as the race. Takes scrubber, file, otherSounds.
template <typename P, typename T>
void ReadReplay([[maybe_unused]] P& p, [[maybe_unused]] T* t)
{
  p.Flag("scrubber", &t->replay_scrubber);
  p.Words("file", &t->play_file);
  if (!p.Has("file"))
    p.Refuse("file", "is missing: the replay to play");
  p.OneOf("otherSounds", &t->other_sounds, {"full", "quieter", "off"});
}

// WindowNamePicture ("windowNamePicture"): the name in the window's strip as the launcher draws it: the pixels row by
// row, red, green, blue, opacity, as base64. Takes width, height, rgba.
template <typename P, typename T>
void ReadWindowNamePicture([[maybe_unused]] P& p, [[maybe_unused]] T* t)
{
  p.Whole("width", &t->width, 1u, 512u);
  p.Whole("height", &t->height, 1u, 64u);
  p.Words("rgba", &t->rgba);
}

// Taskbar ("taskbar"): the launcher's taskbar button, which the game's window joins; each member goes to Windows as it
// is. Takes id, program, name.
template <typename P, typename T>
void ReadTaskbar([[maybe_unused]] P& p, [[maybe_unused]] T* t)
{
  p.Words("id", &t->id);
  if (!p.Has("id"))
    p.Refuse("id", "is missing: the taskbar button's id, the launcher's program file and its name go together");
  p.Words("program", &t->program);
  if (!p.Has("program"))
    p.Refuse("program", "is missing: the taskbar button's id, the launcher's program file and its name go together");
  p.Words("name", &t->name);
  if (!p.Has("name"))
    p.Refuse("name", "is missing: the taskbar button's id, the launcher's program file and its name go together");
}

